import{z as p,x as d,o,c as B,q as l,j as i,D as r,d as n,s,S as E,b as e}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"Qwen3-VL 与文档 OCR","description":"","frontmatter":{"title":"Qwen3-VL 与文档 OCR","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/qwen3-vl.md","filePath":"llm/qwen3-vl.md","lastUpdated":1791063341000}'),A={name:"llm/qwen3-vl.md"};function m(h,a,c,L,w,V){const t=d("Mermaid");return o(),B("div",null,[a[2]||(a[2]=l('<h1 id="qwen3-vl-与文档-ocr" tabindex="-1">Qwen3-VL 与文档 OCR <a class="header-anchor" href="#qwen3-vl-与文档-ocr" aria-label="Permalink to &quot;Qwen3-VL 与文档 OCR&quot;">​</a></h1><div class="epigraph"><p>为增强真实图像上的 OCR，我们用由粗到细的流水线构造约三千万内部样本，并用专用 OCR 模型与 Qwen2.5-VL 的伪标迭代，无需人工标注。</p><footer>—— Bai 等，Qwen3-VL Technical Report，arXiv:2511.21631</footer></div><p>Qwen3-VL 是通义的视觉–语言基座：稠密 2B/4B/8B/32B，MoE 30B-A3B 与 235B-A22B，原生交错上下文到 <strong>256K</strong>。文档 OCR 不是外挂识别头，而是预训练与后训练里被加厚的一类生成任务——转写、版式 HTML/Markdown、跨页 VQA、定位与 KIE 都走同一套「页图 → SigLIP-2 → merger → Qwen3」。云上的 Qwen-VL-OCR 基于该架构做任务模板；专用 <a href="/llm/qwen35-ocr-model">Qwen3.5-OCR</a> 是下一代产品档。本篇写 3-VL <strong>基座</strong>如何把文档当一等数据，叶子里的 patch merge、DeepStack、MRoPE 只引用不重讲。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>通用 VQA 在自然照片上认物体，笔画宽度往往大于 patch。A4 扫描件、手机拍的发票、截屏表格，文字可能小于一个 patch，连接器再强也是在糊块上做语言建模。文档还要求读序、栏、表、公式，纯字符串 OCR 会把二维结构压扁。Qwen3-VL 要在不训练独立检测–识别流水线的前提下，让 LLM 直接生成带结构的文本，并在数十页 PDF 上做跨页指代。</p><p>分辨率与窗口必须一起解。动态分辨率提高采样密度；256K 窗口使「多页图 + 解析文本」能放进同一前缀。没有长文档数据，窗口只是空 vis；没有高分辨率，长窗口里全是不可读的糊 token。连接器与 <a href="/llm/qwen-vl-patch-merge">patch merge</a> 决定每页有多少视觉 token 进入这 256K，页数预算要从这里反推，而不是按「PDF 有多少页」线性加。</p><h3 id="ocr-是数据问题-也是骨干问题" tabindex="-1">OCR 是数据问题，也是骨干问题 <a class="header-anchor" href="#ocr-是数据问题-也是骨干问题" aria-label="Permalink to &quot;OCR 是数据问题，也是骨干问题&quot;">​</a></h3><p>3-VL 视觉侧改用 <a href="/llm/qwen3-vl-siglip2">SigLIP-2</a> 并在动态分辨率上继续训，与 2.5-VL 从零训 ViT 不同。对比先验偏自然图文对，必须用文字密集样本把骨干从「物体名词」拧到「字形」。报告因此单独写 OCR / 文档解析 / 长文档三节，而不是一句「VLM 当然会 OCR」。</p><p><span class="marginnote">Instruct 与 Thinking 两套后训练在 OCRBench 一类识别基准上可以很接近，思维链主要帮需要推理的图表题（如 CharXiv reasoning）。认字任务不要默认开思考模式加延迟。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><h3 id="由粗到细的-ocr-数据" tabindex="-1">由粗到细的 OCR 数据 <a class="header-anchor" href="#由粗到细的-ocr-数据" aria-label="Permalink to &quot;由粗到细的 OCR 数据&quot;">​</a></h3><p>约 <strong>3000 万</strong> 内部真实场景 OCR 样本：专用 OCR 模型出伪标，再经 Qwen2.5-VL 精炼，无人工逐字标注。多语上，相对 2.5-VL 除中英外的约 10 种语言，再扩 <strong>29</strong> 种，另合成约 3000 万多语 OCR，并收集 100 万以上内部真实多语图。这解释「会更多文种」来自数据，不是换识别头。</p><p><span class="marginnote">术语翻译：「伪标注」就是让已有的旧模型先当「代笔老师」——它看图写字，把写出的结果当训练答案；再用更强模型精炼一遍。好处是三千万样本不用人逐字校对，风险是老师认错的字会被学生继承，所以文中要强调真实图和精炼环节。</span></p><h3 id="文档解析-html-与-markdown-双表示" tabindex="-1">文档解析：HTML 与 Markdown 双表示 <a class="header-anchor" href="#文档解析-html-与-markdown-双表示" aria-label="Permalink to &quot;文档解析：HTML 与 Markdown 双表示&quot;">​</a></h3><p>从 Common Crawl 取约 <strong>300 万</strong> PDF，十类文档各约 30 万，另加约 <strong>400 万</strong> 内部文档。版面模型预测读序与框，Qwen2.5-VL-72B 做区域识别，再组装成对位的解析样本。目标格式包括：<strong>QwenVL-HTML</strong>（元素级框）与 <strong>QwenVL-Markdown</strong>（主要对图和表定位，表用 LaTeX）。合成 HTML 与高质量伪标混合，提高泛化。推理时通用 3-VL 按提示词在这些格式间切换；云上 OCR 产品把格式收成 <code>ocr_options.task</code>。</p><h3 id="长文档-合成多页-跨页-vqa" tabindex="-1">长文档：合成多页 + 跨页 VQA <a class="header-anchor" href="#长文档-合成多页-跨页-vqa" aria-label="Permalink to &quot;长文档：合成多页 + 跨页 VQA&quot;">​</a></h3><p>单页样本合成序列：多页图像在前，OCR/HTML 文本在后，覆盖数十页量级。另从高质量多页 PDF 构造必须跨页、跨图/表/正文的 VQA，问类型配平，避免永远只读第一页。预训练 S3 把序列提到 262144，数据侧重长视频与长文档；后训练 SFT 也分 32K 与 256K 两段，256K 段混入上百页技术文档与整书。</p>',17)),(o(),i(E,null,{default:r(()=>[s(t,{id:"mermaid-49",class:"mermaid",graph:"flowchart%20LR%0A%20%20IMG%5B%22%E9%A1%B5%E5%9B%BE%E5%8A%A8%E6%80%81%E5%88%86%E8%BE%A8%E7%8E%87%22%5D%20--%3E%20SIG%5B%22SigLIP-2%20%E7%BB%A7%E7%BB%AD%E8%AE%AD%22%5D%0A%20%20SIG%20--%3E%20MER%5B%22MLP%20merger%20%2F%20DeepStack%22%5D%0A%20%20MER%20--%3E%20LLM%5B%22Qwen3%20256K%22%5D%0A%20%20HTML%5B%22HTML%20%2F%20Markdown%20%E7%9B%91%E7%9D%A3%22%5D%20--%3E%20LLM%0A%20%20LONG%5B%22%E5%A4%9A%E9%A1%B5%E5%90%88%E6%88%90%20%2B%20%E8%B7%A8%E9%A1%B5%20VQA%22%5D%20--%3E%20LLM%0A%20%20LLM%20--%3E%20OUT%5B%22%E8%BD%AC%E5%86%99%20%2F%20%E7%BB%93%E6%9E%84%20%2F%20%E6%96%87%E6%A1%A3%E9%97%AE%E7%AD%94%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"预训练四段：S0 只训 merger（含 OCR 图文，8K）；S1 全参约 1T；再扩窗到 32K、256K。后训练含 OCR、解析、grounding 在内的 RL 奖励。旗舰 235B-A22B 在 OCRBench、OmniDocBench、DocVQA 等表上作为开源侧文档强点被报告——引用时应对 Instruct/Thinking 分列，且分数随快照变。",-1)),a[4]||(a[4]=e("p",null,[e("span",{class:"marginnote"},"解析数据工厂里有版面模型，那是造监督的工具，不是用户推理图里的必经模块。线上仍是整页（或切片）图像进 VLM。")],-1)),a[5]||(a[5]=e("h2",{id:"机制",tabindex:"-1"},[n("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=e("p",null,[n("文档 VLM 的条件是 \\(p(y\\mid I_{1:P},x)\\)：\\(I\\) 为页图，\\(x\\) 为指令。HTML 监督迫使注意力维护框与嵌套；Markdown 监督更轻、更适合「能读、少框」。跨页 VQA 迫使键集合覆盖非当前页的视觉 token，否则「见图 3」无法落地。256K 提供容量，"),e("a",{href:"/llm/qwen3-vl-interleaved-mrope"},"Interleaved MRoPE"),n(" 给每页自己的高宽格并在序列轴上错开页，避免两页左上角共享同一 \\((h,w)\\)。")],-1)),a[7]||(a[7]=e("p",null,"由粗到细降低人工成本，也把教师模型的系统性偏差写进学生：Qwen2.5-VL 认错的连笔，3-VL 可能继承。多语合成可补字体覆盖，但对真实街景拍糊的泛化仍依赖那 100 万真实图。Thinking 变体把 CoT 写进 \\(y\\)，对「这张表是否与后文结论一致」有用，对「把这行字抄下来」往往无增益。",-1)),(o(),i(E,null,{default:r(()=>[s(t,{id:"mermaid-65",class:"mermaid",graph:"flowchart%20LR%0A%20%20P%5B%22%E4%B8%80%E9%A1%B5%20A4%20%E6%89%AB%E6%8F%8F%E4%BB%B6%22%5D%20--%3E%20CUT%5B%22%E5%88%87%E6%88%90%20patch%20%E7%BD%91%E6%A0%BC%22%5D%0A%20%20CUT%20--%3E%20MG%5B%222x2%20merge%20%E5%9B%9B%E6%A0%BC%E5%B9%B6%E4%B8%80%E6%A0%BC%22%5D%0A%20%20MG%20--%3E%20TK%5B%22%E6%AF%8F%E9%A1%B5%E7%BA%A6%E5%90%88%E4%B8%A4%E4%B8%89%E5%8D%83%E8%A7%86%E8%A7%89%20token%22%5D%0A%20%20TK%20--%3E%20N%5B%22256K%20%E7%AA%97%E5%8F%A3%20%E2%89%88%20%E5%8F%AF%E5%AE%B9%E7%BA%B3%E8%BF%91%E7%99%BE%E9%A1%B5%22%5D%0A%20%20N%20--%3E%20WARN%5B%22%E8%B6%85%E9%95%BF%20PDF%20%E4%BB%8D%E9%9C%80%E5%88%87%E5%88%86%E7%AD%96%E7%95%A5%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=l('<p><span class="marginnote">数字实例：视觉 token 是页数预算的单位。粗略算：A4 扫描件按常见配置切格、再做 2×2 合并后，一页约折合两三千个 token；\\(256\\mathrm{K}\\approx262{,}144\\)，除下来大约能装近百页图文。所以「一次读 500 页」不是窗口问题，是要不要分批的问题。</span></p><p>Qwen-VL-OCR 产品在 3-VL 之上加任务模板与旋转矫正等接口，见 <a href="/llm/qwen-vl-ocr-tasks">内置任务</a> 与 <a href="/llm/qwen-ocr-coarse-to-fine">粗到细</a>。基座能力是上限：模板不能让没看见的笔画变成正确 <code>rowspan</code>。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>256K 含视觉 token，页数 × 每页 merge 后的 patch 会先打满窗口。超长 PDF 仍要切分，切分策略错误会丢掉跨文件表头，见 <a href="/llm/qwen-ocr-long-pdf">长 PDF</a>。扫描件加密、极细字、极端旋转，要靠旋转与分辨率策略，不是 235B 自动解决。化学式、乐谱等在报告里作为解析标签出现，生产准确率应单测，不能用 DocVQA 总分代替。</p><p>3-VL 仍吃图像；原生 PDF 字节流是 <a href="/llm/qwen35-ocr">Qwen3.5-OCR</a> 的产品能力，不要写进 3-VL 基座。开源权重与云上 <code>qwen-vl-ocr-*</code> 快照的任务覆盖、max_tokens 默认值并不相同。幻觉字段在 KIE 上仍然存在：过密过糊会编造笔画。</p><p><span class="marginnote">常见误区：初学者容易把识别错当成「看不清，输出空着」。实际上图像过密过糊时，模型常常会「编」一个看起来合理的金额或日期补上——字段级幻觉不报错、格式还对，最危险。用 KIE（关键信息抽取）出合同、发票数字时必须抽样人工核对。</span></p><p><span class="marginnote">评文档 OCR 至少三张表：字符/字段准确、结构（表 HTML / 框）、跨页问答。只报 OCRBench 会选出「会念字、不会读表」的检查点。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Qwen3-VL 用 SigLIP-2 + Qwen3、原生 256K 交错上下文，把 OCR 与文档解析写成预训练主数据，而不是插件头。</li><li>OCR：约 3e7 内部样本粗到细伪标，多语再扩 29 种；解析用 HTML/Markdown 双目标；长文档靠多页合成与跨页 VQA。</li><li>云上 Qwen-VL-OCR 基于该架构做任务契约；原生 PDF 多轮属于 3.5-OCR 产品线。</li><li>Instruct/Thinking 在纯识别上未必分出高下；推理题再开思考。</li><li>出处：Bai 等，<em>Qwen3-VL Technical Report</em>，arXiv:2511.21631。对照 Wang 等 Qwen2-VL、Qwen2.5-VL 技术报告的文档章节。</li></ul>',9))])}const R=p(A,[["render",m]]);export{C as __pageData,R as default};
